{
  "query": "query MisMarcaciones($take: Int, $cursor: ID, $dateFrom: String, $dateTo: String) {
  misMarcaciones(take: $take, cursor: $cursor, dateFrom: $dateFrom, dateTo: $dateTo) {
    edges {
      cursor
      node {
        id
        eventType
        status
        locationName
        timestamp
        workDate
        distanceMeters
        rejectionReason
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}",
