{
  "query": "mutation CreateSupplier($input: CreateSupplierInput!) { createSupplier(input: $input) { id logistics { status leadTimeDays } } }",
  "variables": {
    "input": {
      "razonSocial": "Proveedor Logística Draft",
      "nit": "901{{$timestamp}}",
      "tipo": "PERSONA_JURIDICA",
      "condicionPago": "DIAS_30",
      "saveLogisticsAsDraft": true,
      "logistics": {
        "leadTimeDays": 2,
        "deliveryDays": [1, 3]
      }
    }
  }
}

{
  "query": "mutation UpdateSupplier($id: ID!, $input: UpdateSupplierInput!) { updateSupplier(id: $id, input: $input) { id logistics { status leadTimeDays deliveryMode transportType } } }",
  "variables": {
    "id": "{{supplierId}}",
    "input": {
      "saveLogisticsAsDraft": false,
      "logistics": {
        "deliveryMode": "SUPPLIER_DELIVERS",
        "deliveryPlace": "PLANT",
        "deliveryDays": [1, 2, 3, 4, 5],
        "leadTimeDays": 5,
        "receptionResponsibleUserId": "{{receptionUserId}}",
        "transportType": "OWN",
        "requiresColdChain": false,
        "coverageLocationIds": ["{{locationId}}"]
      }
    }
  }
}

{
  "query": "query Supplier($id: ID!) { supplier(id: $id) { id logistics { status leadTimeDays coverageLocations { id name } } } }",
  "variables": { "id": "{{supplierId}}" }
}

{
  "query": "query History($supplierId: ID!) { supplierLogisticsHistory(supplierId: $supplierId) { id action changes { field oldValue newValue } } }",
